package com.ruoyi.medical.persistence;

import com.ruoyi.medical.identity.ServiceCertificateIdentity;
import com.ruoyi.medical.workflow.TaskRunActivitySchema;
import java.time.Duration;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.*;

/** No Temporal worker, run creator or RN01 admission is enabled by this slice. */
@Configuration(proxyBeanMethods=false)
@ConditionalOnProperty(name="medical.task-run.activities.server-enabled",havingValue="true",matchIfMissing=false)
class TaskRunActivityConfiguration {
    @Bean(name="taskRunActivityServerSchema")TaskRunActivitySchema schema(){return new TaskRunActivitySchema();}
    @Bean TaskRunDispatchReservation taskRunDispatchReservation(@Qualifier("masterDataSource")DataSource data,TaskNodeInputAuthority inputs,@Qualifier("formalRunServiceIdentity")ServiceCertificateIdentity identity,PermissionSchema json){return new TaskRunDispatchReservation(data,inputs,identity,json);}
    @Bean TaskRunActivityEndpointFactory taskRunActivityEndpointFactory(@Qualifier("masterDataSource")DataSource data,TaskRunActivityPreparation preparation,TaskNodeInputAuthority inputs,
            FormalTaskNodeAuthority nodes,FormalRunRecoveryAccess recovery,TaskRunLaunchRecoveryAuthority launches,TaskRunWorkflowLedger workflow,TaskRuntimeJournal journal,TaskResearchCommitService commits,
            TaskRunDispatchReservation reservations,RunTokenAuthority tokens,TaskHostControlBootstrap host,TaskProfessionalHostOrchestrator orchestrator,PermissionSchema json,TaskRunLifecycleService lifecycle,
            @Value("${medical.task-run.activities.lease-lifetime-seconds}")long leaseSeconds){
        if(leaseSeconds<1||leaseSeconds>3600)throw new IllegalArgumentException("ACTIVITY_LEASE_CONFIGURATION_REQUIRED");
        return new TaskRunActivityEndpointFactory(data,preparation,inputs,nodes,recovery,launches,workflow,journal,commits,reservations,tokens,host,orchestrator,json,Duration.ofSeconds(leaseSeconds),lifecycle);
    }
    @Bean TaskRunLifecycleAuthority taskRunLifecycleAuthority(@Qualifier("masterDataSource")DataSource data,FormalRunControlAccess controls,AgentPublicationAuthority publications,AgentExecutionPolicyAuthority policies,RuntimeRetentionAuthority retention,com.ruoyi.medical.identity.IdentityDirectoryPolicy identity,TaskRunLaunchRecoveryAuthority launches,TaskRunWorkflowLedger workflow,TaskRunGraphService graphs,PermissionSchema json){return new TaskRunLifecycleAuthority(data,controls,publications,policies,retention,identity,launches,workflow,graphs,json);}
    @Bean TaskRunTerminationFacts taskRunTerminationFacts(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskInvocationRecords invocations,FormalInvocationSettlement settlements,TaskProfessionalSupervisor supervisor,TaskProfessionalRuntimeService.Deployment deployment,TaskRuntimeJournal runtime,@Value("${medical.task-run.activities.maximum-termination-facts}")int maximum,org.springframework.beans.factory.ObjectProvider<TaskRunStageCommitServiceV2> stages,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterLifecycleFacts> writerFacts,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierLifecycleFacts> verifierFacts,FormalInvocationCancellation cancellation,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterSupervisor> writerSupervisor,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterDeployment> writerDeployment,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierSupervisor> verifierSupervisor,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierDeployment> verifierDeployment){var facts=new TaskRunTerminationFacts(data,json,invocations,settlements,supervisor,deployment,runtime,maximum,stages);facts.partialSupervisors(writerSupervisor,writerDeployment,verifierSupervisor,verifierDeployment);facts.cancellation(cancellation);facts.writerFacts(writerFacts);facts.verifierFacts(verifierFacts);return facts;}
    @Bean TaskRunTerminationReconciler taskRunTerminationReconciler(TaskRunLifecycleAuthority authority,TaskRunTerminationFacts facts,TaskProfessionalSupervisor supervisor,TaskProfessionalRuntimeService.Deployment deployment,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterSupervisor> writers,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterDeployment> writerDeployment,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierSupervisor> verifiers,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierDeployment> verifierDeployment){return new TaskRunTerminationReconciler(authority,facts,supervisor,deployment,writers,writerDeployment,verifiers,verifierDeployment);}
    @Bean TaskRunLifecycleService taskRunLifecycleService(@Qualifier("masterDataSource")DataSource data,PermissionSchema json,TaskRunLifecycleAuthority authority,FormalRunRecoveryAccess recovery,TaskRunLaunchRecoveryAuthority launches,TaskRunWorkflowLedger workflow,TaskRuntimeJournal runtime,TaskResearchCommitService commits,TaskRunTerminationFacts facts,TaskNodeInputAuthority inputs,org.springframework.beans.factory.ObjectProvider<TaskRunWaitingCommitService> waiting,org.springframework.beans.factory.ObjectProvider<TaskRunStageCommitServiceV2> stages,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterStageCommitService> writerStages,org.springframework.beans.factory.ObjectProvider<TaskSectionWriterLifecycleFacts> writerFacts,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierStageCommitService> verifierStages,org.springframework.beans.factory.ObjectProvider<TaskSourceVerifierLifecycleFacts> verifierFacts,org.springframework.beans.factory.ObjectProvider<TaskCandidateAssemblyStageJournal> assemblyStages,TaskRunTerminationReconciler reconciler){var service=new TaskRunLifecycleService(data,json,authority,recovery,launches,workflow,runtime,commits,facts,inputs,waiting,stages);service.writerStages(writerStages);service.writerFacts(writerFacts);service.verifierStages(verifierStages);service.verifierFacts(verifierFacts);service.assemblyStages(assemblyStages);service.terminationReconciler(reconciler);return service;}
}
